Check 'World Preview Safety' 'Preview is expiring single-use and only stages a bounded validated archive outside saves' ($worldTransactionService -match 'PreviewLifetime' -and $worldTransactionService -match 'plans\.Remove\(request\.PreviewToken\)' -and $worldTransactionService -match 'MaximumArchiveBytes' -and $worldTransactionService -match '20,000-entry limit' -and $worldTransactionService -match 'unsafe path' -and $worldTransactionService -match 'world-transactions')
Check 'Recovery Capability Truth' 'Player recovery accepts only canonical save identities while Base binary repair remains visibly unavailable and Guild ownership repair is truthfully shown as live' ($worldTransactionService -match 'player-recovery' -and $worldTransactionService -match 'IsCanonicalPlayerSave' -and $ui -match 'Base ownership/Palbox binary repair remains BACKEND REQUIRED' -and $ui -match 'Guild ownership repair \(Claim/Transfer/Add Player\) is live from the Guilds page' -and $worldTransactionDtos -match 'WorldImportPreviewDto')
Check 'Transaction Center' 'Durable transaction history is server-side remote-safe evidence' ($ui -match 'Transaction Center / Durable Journal' -and $vm -match '_api\.GetWorldTransactionsAsync' -and $client -match '/api/v1/world/transactions' -and $apiHostSource -match '/api/v1/world/transactions' -and $worldTransactionService -match 'GetHistory')
Check 'World Mutation Failure Tests' 'Runtime smoke injects every mandatory failure stage only behind an explicit test switch' ((Text 'scripts\Test-v0.5.3.0-RuntimeSmoke.ps1') -match "@\('preview','backup','staging','swap','validation'\)" -and $apiHostSource -match 'MYSTTIQ_ENABLE_FAILURE_INJECTION' -and $apiHostSource -match 'X-MystTiq-Test-Failure-Stage')
Check 'Crash Analyzer Wiring' 'Crash analysis follows View through ViewModel and API client to the headless evidence service' ($ui -match 'AnalyzeCrashesCommand' -and $vm -match '_api\.AnalyzeCrashesAsync' -and $api -match 'AnalyzeCrashesAsync' -and $client -match '/api/v1/crash-analyzer/analyze' -and $apiHostSource -match '/api/v1/crash-analyzer/history' -and $crashSaveService -match 'class HeadlessCrashAndSaveToolsService')
Check 'Crash Evidence Integrity' 'Analysis is bounded, persistent, and refuses to invent causality from weak proximity' ($crashSaveService -match 'MaximumLogFiles = 12' -and $crashSaveService -match 'MaximumLogLines = 4000' -and $crashSaveService -match 'crash-analyzer' -and $crashSaveService -match 'without claiming an unproven cause' -and $ui -match 'never promotes a successful-load line')
Check 'Crash Isolation Safety' 'Isolation guidance preserves evidence and backup before recommending one-at-a-time MOD isolation' ($crashSaveService -match 'Preserve the current logs and create a verified backup' -and $crashSaveService -match 'disable one recently changed UE4SS mod at a time' -and $crashSaveService -notmatch 'File\.Delete|Directory\.Delete')
Check 'Save Tools Wiring' 'Save diagnostics follow View through ViewModel and API client to server-side routes' ($ui -match 'RunSaveToolsSelfTestCommand' -and $vm -match '_api\.RunSaveToolsSelfTestAsync' -and $api -match 'GetSaveFilesAsync' -and $client -match '/api/v1/save-tools/self-test' -and $apiHostSource -match '/api/v1/save-tools/files')
Check 'Save Tools Coverage' 'Diagnostics cover Python, legacy converter, PlM converter, Oodle and active save signature' ($crashSaveService -match 'Python' -and $crashSaveService -match 'palworld-save-tools' -and $crashSaveService -match 'palworld-plm-tools' -and $crashSaveService -match 'oo2core' -and $crashSaveService -match 'ReadSignature' -and $crashSaveDtos -match 'ActiveLevelSignature')
Check 'Save Tools Read Only' 'Save inspection is bounded and mutation remains behind World Transactions' ($crashSaveService -match 'MaximumSaveFiles = 5000' -and $crashSaveService -notmatch 'File\.WriteAllText\(.*Level|File\.Move\(.*Level|File\.Delete\(.*sav' -and $ui -match 'Inspection is read-only' -and $ui -match 'World Transaction workflow')
Check 'Crash Save Remote Safety' 'Desktop consumes only API DTOs and never scans server logs or saves locally' ($vm -match '_api\.GetCrashHistoryAsync' -and $vm -match '_api\.GetSaveFilesAsync' -and $vm -notmatch 'Directory\.EnumerateFiles.*(?:log|sav)' -and $crashSaveDtos -notmatch 'ServerRoot')
Check 'Crash Save Polling' 'Crash and save tools are on-demand and do not add a timer' ($vm -match 'RefreshCrashHistoryAsync' -and $vm -match 'RefreshSaveToolsAsync' -and $vm -notmatch 'DispatcherTimer.*(?:Crash|SaveTools)')
Check 'Workspace Parity' 'Workspace refresh validate browse open and save paths are restored' ($ui -match 'ValidateWorkspaceCommand' -and $ui -match 'WorkspaceBrowse_Click' -and $ui -match 'WorkspaceOpen_Click' -and $ui -match 'SaveConfigurationCommand' -and $vm -match 'ValidateWorkspacePaths' -and $vm -match '_api\.SaveEditableConfigurationAsync')
Check 'Workspace Remote Safety' 'Local shell and picker actions are profile-gated and remote profiles receive explicit guidance' ($ui -match 'IsEnabled="\{Binding IsLocalProfile\}"' -and $mainWindowCode -match '!vm\.IsLocalProfile' -and $vm -match 'Open is unavailable for remote profiles' -and $vm -match 'remote paths never invoke the desktop shell|server paths do not belong to this computer')
Check 'Diagnostics Closeout' 'Diagnostics supports copy export redacted package and local diagnostics opening' ($ui -match 'ExportNetworkDiagnosticReport_Click' -and $ui -match 'CreateSupportPackage_Click' -and $ui -match 'Open Local Diagnostics' -and $mainWindowCode -match 'ZipArchiveMode\.Create' -and $mainWindowCode -match 'diagnostics\.txt' -and $vm -match 'BuildRedactedSupportReport')
Check 'Support Redaction' 'Support output never includes bearer token or certificate-pin values and strips URL credentials/query/fragment' ($vm -match 'Authentication supplied:.+redacted' -and $vm -match 'TLS pin supplied:.+redacted' -and $vm -match 'UserName = string\.Empty' -and $vm -match 'Password = string\.Empty' -and $vm -match 'Query = string\.Empty' -and $vm -match 'Fragment = string\.Empty' -and $vm -notmatch '\$"Bearer token: \{BearerToken\}')
Check 'Settings Security Closeout' 'Profiles LAN discovery TLS pin bearer handling and explicit local bootstrap remain visible' ($ui -match 'Discover LAN Services' -and $ui -match 'Bootstrap Local Service' -and $ui -match 'Bearer token' -and $ui -match 'TLS SHA-256 pin' -and $vm -match 'BootstrapLocalAsync' -and $vm -match 'Bearer token is process-memory-only')
Check 'Final Event Coverage' 'All 287 historical event rows have one allowed non-empty classification and evidence' ($coverage.Count -eq 287 -and @($coverage | Where-Object { $_.Classification -notin @('Mapped','Intentionally obsolete','Visibly unavailable','BACKEND REQUIRED') -or [string]::IsNullOrWhiteSpace($_.CurrentMapping) -or [string]::IsNullOrWhiteSpace($_.Evidence) }).Count -eq 0)
Check 'Restoration Closeout' 'Parity audit and roadmap retain the final coverage and pre-v0.5 boundary' ((Text 'docs\GUI_EVENT_COVERAGE_v0.5.3.0.md') -match '\*\*287\*\*' -and $parityMatrix -match '\| Workspace \| Migrated / closeout' -and $parityMatrix -match '\| Diagnostics Center \| Migrated / closeout' -and $road -match 'v0\.4\.18\.2 — Workspace \+ Diagnostics \+ Settings Closeout')
Check 'Exit UX' 'Tray exposes safe force and GUI-only exit choices' ($appComposition -match 'SafeExit_OnClick' -and $appComposition -match 'ForceExit_OnClick' -and (Text 'src\MystTiq.Desktop\App.axaml') -match 'Safe Exit' -and (Text 'src\MystTiq.Desktop\App.axaml') -match 'Force Exit' -and (Text 'src\MystTiq.Desktop\App.axaml') -match 'Exit GUI Only')
Check 'Exit UX' 'Safe exit uses graceful lifecycle stop before owned sidecar shutdown' ($vm -match 'ShutdownForExitAsync' -and $vm -match '_api\.StopServerAsync' -and $appComposition -match 'StopOwnedSidecarAsync')
Check 'Exit UX' 'Force exit uses dedicated lifecycle force-stop API route' ($client -match '/api/v1/server/force-stop' -and $apiHostSource -match '/api/v1/server/force-stop' -and $apiHostSource -match 'StopAsync\(TimeSpan\.Zero')

Check 'Behavioral Contract' 'Aggregate wire sample accepts null lifecycle transition timestamp before first transition' ($null -eq $sample.status.lastTransitionAt)
Check 'Behavioral Contract' 'Aggregate wire sample preserves coherent server/service/player/metric/log state' (-not $sample.status.ready -and $sample.service.activeState -eq 'active' -and $sample.players.onlineCount -eq 3 -and $sample.metrics.threadCount -eq 42 -and $sample.logTail.lines[0] -eq 'ready')

if($RunBuild){
    & (Join-Path $root 'Build.ps1') -Action Validate -StrictValidation
    & (Join-Path $root 'Build.ps1') -Action Build -Configuration Release
    & (Join-Path $root 'Build.ps1') -Action WindowsHeadless -Configuration Release
    & (Join-Path $root 'Build.ps1') -Action LinuxHeadless -Configuration Release
    & (Join-Path $root 'Build.ps1') -Action DesktopWindows -Configuration Release
    & (Join-Path $root 'Build.ps1') -Action DesktopLinux -Configuration Release
    & (Join-Path $root 'scripts\Test-v0.5.3.0-RuntimeSmoke.ps1') -ProjectRoot $root
}

