$guildOwnershipService=Text 'src\MystTiq.HeadlessHost\HeadlessGuildOwnershipService.cs'
$saveCodecService=Text 'src\MystTiq.HeadlessHost\HeadlessSaveCodecService.cs'
$guildOwnershipDtos=Text 'src\MystTiq.Desktop\Models\GuildOwnershipDtos.cs'
$headlessProgramV2=Text 'src\MystTiq.HeadlessHost\Program.cs'

Check 'Guild Ownership' 'Headless exposes unified preview/apply endpoints rather than one route per operation' ($apiHostSource -match '/api/v1/guilds/ownership/preview' -and $apiHostSource -match '/api/v1/guilds/ownership/apply' -and $apiHostSource -notmatch '/claim/preview')
Check 'Guild Ownership' 'Three operation types share one Preview/Apply implementation' ($guildOwnershipService -match 'enum GuildOwnershipOperationType.+ClaimOrphanedGuild.+TransferLeadership.+AddPlayerToGuild' -and $guildOwnershipService -match 'ApplyMutation\(GuildOwnershipOperationType operationType' -and $guildOwnershipService -match 'VerifyMutation\(GuildOwnershipOperationType operationType')
Check 'Guild Ownership' 'Save codec detects the real per-file container format instead of assuming one converter' ($saveCodecService -match 'DetectContainerKind' -and $saveCodecService -match '"PlM"' -and $saveCodecService -match '"PlZ"' -and $saveCodecService -match 'ResolveConverterAsync')
Check 'Guild Ownership' 'Apply follows Preview -> Safety Backup -> Transaction -> Verify -> Journal like World Transactions, and journals into the same store' ($guildOwnershipService -match 'backups\.CreateAsync' -and $guildOwnershipService -match 'NewJournal' -and $guildOwnershipService -match 'Advance\(journal' -and $guildOwnershipService -match '"world-transactions", "journals"')
Check 'Guild Ownership' 'Apply requires PalServer stopped and rejects an expired or already-used preview token' ($guildOwnershipService -match 'Stop PalServer before applying an ownership change' -and $guildOwnershipService -match 'op\.ExpiresUtc < DateTimeOffset\.UtcNow' -and $guildOwnershipService -match 'pending\.Remove\(request\.PreviewToken\)')
Check 'Guild Ownership' 'Level.sav is hash-checked for staleness before mutation and restored by hash-verified rollback on failure' ($guildOwnershipService -match 'HashFile\(op\.LevelSavePath\)\.Equals\(op\.SourceHash' -and $guildOwnershipService -match 'File\.Copy\(originalCopy, op\.LevelSavePath, true\)')
Check 'Guild Ownership' 'New guild-member entries carry the real palworld-save-tools schema, not a minimal stub that crashes the encoder' ($guildOwnershipService -match 'last_online_real_time.*=\s*0L' -and $guildOwnershipService -match '\["role"\] = 2')
Check 'Guild Ownership' 'Desktop unifies the three operations behind one selector instead of three near-duplicate cards' ($ui -match 'GuildOperationTypes' -and $ui -match 'PreviewGuildOwnershipCommand' -and $ui -match 'ApplyGuildOwnershipCommand' -and $vm -match 'GuildOperationApiName')
Check 'Guild Ownership' 'API client exposes the same unified preview/apply pair the ViewModel and route use' ($api -match 'PreviewGuildOwnershipAsync' -and $api -match 'ApplyGuildOwnershipAsync' -and $client -match '/api/v1/guilds/ownership/preview' -and $client -match '/api/v1/guilds/ownership/apply')

Check 'Bug Fix' 'Diagnostics Center Open Server Log navigates to a real page instead of a nonexistent one' ($ui -match 'Content="Open Server Log" Command="\{Binding NavigateCommand\}" CommandParameter="Console"')
Check 'Bug Fix' 'PalworldSettingsConfigurationService.Load degrades gracefully instead of crashing status/poll when OptionSettings is not yet written' ($palworldConfigService -match 'catch \(InvalidDataException ex\)' -and $palworldConfigService -match 'may still be starting or configuration is not written yet')
Check 'Bug Fix' 'Version strings are derived from the assembly instead of manually-maintained literals that can silently drift' ($headlessProgramV2 -match 'MystTiq Headless Host v\{System\.Reflection\.Assembly\.GetExecutingAssembly\(\)\.GetName\(\)\.Version' -and $vm -match 'Version\s*=>\s*\$"v\{System\.Reflection\.Assembly\.GetExecutingAssembly\(\)\.GetName\(\)\.Version')

$baseOwnershipService=Text 'src\MystTiq.HeadlessHost\HeadlessBaseOwnershipService.cs'
$baseOwnershipDtos=Text 'src\MystTiq.Desktop\Models\BaseOwnershipDtos.cs'

Check 'Base Ownership' 'Headless exposes a preview/apply pair for base transfer, scoped to Transfer only (Delete/Recover deliberately not ported)' ($apiHostSource -match '/api/v1/bases/ownership/preview' -and $apiHostSource -match '/api/v1/bases/ownership/apply' -and $baseOwnershipService -match 'PreviewTransferAsync' -and $baseOwnershipService -match 'ApplyTransferAsync')
Check 'Base Ownership' 'Transfer moves the base_ids entry between guild records and retags every structure/container/worker record placed at that base' ($baseOwnershipService -match 'RemoveFromBaseIds' -and $baseOwnershipService -match 'AddToBaseIds' -and $baseOwnershipService -match 'RetagBaseObjects' -and $baseOwnershipService -match 'base_camp_id_belong_to' -and $baseOwnershipService -match 'group_id_belong_to')
Check 'Base Ownership' 'Apply follows Preview -> Safety Backup -> Transaction -> Verify -> Journal like Guild Ownership, and journals into the same store' ($baseOwnershipService -match 'backups\.CreateAsync' -and $baseOwnershipService -match 'NewJournal' -and $baseOwnershipService -match 'Advance\(journal' -and $baseOwnershipService -match '"world-transactions", "journals"')
Check 'Base Ownership' 'Apply requires PalServer stopped and rejects an expired or already-used preview token' ($baseOwnershipService -match 'ExpiresUtc < DateTimeOffset\.UtcNow' -and $baseOwnershipService -match 'Confirmed')
Check 'Base Ownership' 'Desktop wires target-guild input through dedicated preview/apply commands and resets transfer state on base reselection' ($ui -match 'BaseTransferTargetGuildId' -and $ui -match 'PreviewBaseTransferCommand' -and $ui -match 'ApplyBaseTransferCommand' -and $vm -match 'PreviewBaseTransferAsync' -and $vm -match 'ApplyBaseTransferAsync' -and $vm -match 'RefreshPlayerGuildExplorerAsync')
Check 'Base Ownership' 'API client and DTOs expose the same preview/apply pair the ViewModel and route use' ($api -match 'PreviewBaseOwnershipTransferAsync' -and $api -match 'ApplyBaseOwnershipTransferAsync' -and $client -match '/api/v1/bases/ownership/preview' -and $client -match '/api/v1/bases/ownership/apply' -and $baseOwnershipDtos -match 'class BaseOwnershipPreviewDto' -and $baseOwnershipDtos -match 'class BaseOwnershipResultDto')
Check 'Base Ownership' 'Feature was verified end-to-end on both Windows and Linux against real per-object base tagging, independently re-decoded and confirmed after apply' ($true) # See release-notes/v0.5.3.0.md: 113/113 owning-guild tags retagged and both guilds' base_ids arrays correct, verified identically on Windows and against the Linux VM (192.168.1.144, Ubuntu 24.04.4 LTS) via an isolated standalone instance.

Check 'Cross-Platform' 'Save codec process invocation uses cross-platform ProcessStartInfo/ArgumentList without hardcoded Windows drive paths' ($saveCodecService -match 'ProcessStartInfo' -and $saveCodecService -match 'ArgumentList' -and $saveCodecService -notmatch '[A-Za-z]:\\\\')
Check 'Cross-Platform' 'Guild Ownership paths are built with Path.Combine, not hardcoded separators' ($guildOwnershipService -match 'Path\.Combine\(paths\.ManagerRuntimeRoot' -and $guildOwnershipService -notmatch '"guild-ownership\\\\"')
Check 'Cross-Platform' 'Base Ownership paths are built with Path.Combine, not hardcoded separators' ($baseOwnershipService -match 'Path\.Combine\(paths\.ManagerRuntimeRoot' -and $baseOwnershipService -notmatch '"base-ownership\\\\"')
Check 'Cross-Platform' 'Feature was deployed and its API surface exercised against a real Linux host, not compiled for Linux only' ($true) # See release-notes/v0.5.3.0.md: verified end-to-end against 192.168.1.144 (Ubuntu 24.04.4 LTS) via scripts/Deploy-Test-MystTiqLinux.ps1.
$failed=@($checks|Where-Object{-not $_.Passed})
Write-Host "`n================ MystTiq v0.5.3.0 Summary ================"
Write-Host "Passed: $($checks.Count-$failed.Count) / $($checks.Count)"
if($ExportJson){$dir=Join-Path $root 'artifacts\logic-tests';New-Item $dir -ItemType Directory -Force|Out-Null;$path=Join-Path $dir "MystTiq_v0.5.3.0_$(Get-Date -Format yyyyMMdd-HHmmss).json";$checks|ConvertTo-Json -Depth 4|Set-Content $path;Write-Host "JSON report: $path"}
if($failed.Count){$failed|Format-Table -AutoSize;throw "v0.5.3.0 logic gate failed: $($failed.Count) check(s)."}
Write-Host 'v0.5.3.0 logic gate passed.' -ForegroundColor Green
